package com.decimal128.textcodec

import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * Render vectors for [Decimal128TextCodec.dpd128ToString].
 *
 * Every expected pairing was taken from the shared `string_bid_dpd` corpus,
 * which is generated by the decimal128-c engine, so these are an independent
 * oracle rather than this codec grading itself. They are chosen to cover the
 * surfaces the DPD layout actually distinguishes: both combination-field
 * cases, the exponent extremes, and coefficients that exercise every declet.
 */
class TestDpd128ToString {

    data class TC(val hexStr: String, val expected: String)

    val tcs = arrayOf(
// === Specials: identical bit patterns to BID, no coefficient to lay out ===
        TC("[7800000000000000,0000000000000000]", "Infinity"),
        TC("[F800000000000000,0000000000000000]", "-Infinity"),
        TC("[7C00000000000000,0000000000000000]", "NaN"),
        TC("[FC00000000000000,0000000000000000]", "-NaN"),
        TC("[7E00000000000000,0000000000000000]", "sNaN"),

// === Case A: leading digit 0..7, exponent MSBs in G0G1 ===
        TC("[2208000000000000,0000000000000000]", "0"),
        TC("[A208000000000000,0000000000000000]", "-0"),
        TC("[2208000000000000,0000000000000001]", "1"),
        TC("[A208000000000000,0000000000000001]", "-1"),
        TC("[2208000000000000,0000000000000009]", "9"),

// === Case B: leading digit 8 or 9, exponent MSBs displaced into G2G3 ===
        TC("[2208800000000000,0000000000000008]", "8E+2"),
        TC("[220B400000000000,0000000000000008]", "8E+13"),
        TC("[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]", "9999999999999999999999999999999999"),

// === Exponent extremes ===
        TC("[47FFC00000000000,0000000000000000]", "1.000000000000000000000000000000000E+6144"),
        TC("[47FFC033790A64F9,FE910BDA994B3322]", "1.003198280313997724281686314944622E+6144"),
        TC("[0000000000000000,0000000000000000]", "0E-6176"),
        TC("[8000000000000000,0000000000000000]", "-0E-6176"),
        TC("[0000000000000000,0000000000000009]", "9E-6176"),
        TC("[0001000000000000,0000000000000009]", "9E-6172"),

// === Coefficients with runs of zero declets ===
        TC("[2202C00000000000,0020000000000000]", "0.000008000000000000000"),
        TC("[23DE400000000002,0000000000000000]", "2.0000000000000000000E+1900"),
    )

    @Test
    fun testCases() {
        for (tc in tcs) {
            val hi = tc.hexStr.substring(1, 17).toULong(16).toLong()
            val lo = tc.hexStr.substring(18, 34).toULong(16).toLong()
            assertEquals(tc.expected, Decimal128TextCodec.dpd128ToString(hi, lo), "for ${tc.hexStr}")
        }
    }

    /** The two formats must agree on every value: same text from peer encodings. */
    @Test
    fun dpdAndBidAgree() {
        val pairs = arrayOf(
            "[3040000000000000,0000000000000001]" to "[2208000000000000,0000000000000001]", // 1
            "[3040000000000000,0000000000000009]" to "[2208000000000000,0000000000000009]", // 9
            "[7800000000000000,0000000000000000]" to "[7800000000000000,0000000000000000]", // Infinity
            "[3041ED09BEAD87C0,378D8E63FFFFFFFF]" to "[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]", // 34 nines
        )
        for ((bidHex, dpdHex) in pairs) {
            val bh = bidHex.substring(1, 17).toULong(16).toLong()
            val bl = bidHex.substring(18, 34).toULong(16).toLong()
            val dh = dpdHex.substring(1, 17).toULong(16).toLong()
            val dl = dpdHex.substring(18, 34).toULong(16).toLong()
            assertEquals(
                Decimal128TextCodec.bid128ToString(bh, bl),
                Decimal128TextCodec.dpd128ToString(dh, dl),
                "peer encodings disagree: $bidHex vs $dpdHex"
            )
        }
    }
}
